# -*- coding: utf-8 -*-
# HFSS (AEDT) IronPython script -- sub6 edge-diode cell EIGENMODE "EDGE_ON_along" (generated by lwmom). NOT run in AEDT by the author. MODEL_ONLY predictions: README / predictions.json.
# Run inside AEDT: Tools > Run Script...   NOT run in AEDT by the author: check the boundary dialogs (see README).
#   cell 6.4 x 6.4 mm, RT/duroid 5880 (eps_r 2.2, tan d 0.0009) 1.575 mm on a PEC ground, air up to 60.0 mm
#   with a PEC lid, patch: circle D = 0 mm (see body)
#   Master/slave pairs in x and y with Bloch phase: phase_x, phase_y (design variables).
import ScriptEnv
ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
oDesktop.RestoreWindow()
oProject = oDesktop.NewProject()
oProject.InsertDesign("HFSS", "EDGE_ON_along", "Eigenmode", "")
oDesign = oProject.SetActiveDesign("EDGE_ON_along")
oEditor = oDesign.SetActiveEditor("3D Modeler")
oEditor.SetModelUnits(["NAME:Units Parameter", "Units:=", "mm", "Rescale:=", False])

P = 11.6; H = 3.175; LID = 60.0; RD = 5.3; GAP = 1; SW = 0.35; TAB = 0.02
SLOT_L = 7.42; SLOT_W = 2.4
PHASE_X = "0.000deg"     # along x: 0.000 deg, 0 deg; along the diagonal: 0 deg, 0 deg
PHASE_Y = "84.817deg"

oProject.GetDefinitionManager().AddMaterial(["NAME:HMSA_substrate", "CoordinateSystemType:=", "Cartesian",
    "BulkOrSurfaceType:=", 1, ["NAME:PhysicsTypes", "set:=", ["Electromagnetic"]],
    "permittivity:=", "2.2", "dielectric_loss_tangent:=", "0.0009"])

def attrs(name, material, solve_inside, color="(255 128 0)", transp=0):
    return ["NAME:Attributes", "Name:=", name, "Flags:=", "", "Color:=", color, "Transparency:=", transp,
            "PartCoordinateSystem:=", "Global", "UDMId:=", "", "MaterialValue:=", '"' + material + '"',
            "SurfaceMaterialValue:=", '""', "SolveInside:=", solve_inside, "IsMaterialEditable:=", True,
            "UseMaterialAppearance:=", False, "IsLightweight:=", False]

def mm(v):
    return repr(float(v)) + "mm"

# substrate and air column (centred on the origin)
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", mm(-P / 2), "YPosition:=", mm(-P / 2), "ZPosition:=", "0mm",
    "XSize:=", mm(P), "YSize:=", mm(P), "ZSize:=", mm(H)], attrs("Substrate", "HMSA_substrate", True, "(0 128 0)", 0.6))
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", mm(-P / 2), "YPosition:=", mm(-P / 2), "ZPosition:=", mm(H),
    "XSize:=", mm(P), "YSize:=", mm(P), "ZSize:=", mm(LID)], attrs("Air", "air", True, "(143 175 143)", 0.9))


def rect_sheet(name, x0, y0, x1, y1, z):
    oEditor.CreateRectangle(["NAME:RectangleParameters", "IsCovered:=", True, "XStart:=", mm(x0), "YStart:=", mm(y0), "ZStart:=", mm(z),
        "Width:=", mm(x1 - x0), "Height:=", mm(y1 - y0), "WhichAxis:=", "Z"], attrs(name, "vacuum", True))

# two half discs (centres on the cell edges x = -+P/2, radius RD), each minus the half slot (slot along y: length SLOT_L, width SLOT_W)
for nm, cx, sgn in (("PatchL", -P / 2, 1.0), ("PatchR", P / 2, -1.0)):
    oEditor.CreateCircle(["NAME:CircleParameters", "IsCovered:=", True, "XCenter:=", mm(cx), "YCenter:=", "0mm",
        "ZCenter:=", mm(H), "Radius:=", mm(RD), "WhichAxis:=", "Z", "NumSegments:=", "0"], attrs(nm, "vacuum", True))
    rect_sheet(nm + "_slot", min(cx - SLOT_W / 2, cx + SLOT_W / 2), -SLOT_L / 2, max(cx - SLOT_W / 2, cx + SLOT_W / 2), SLOT_L / 2, H)
    oEditor.Subtract(["NAME:Selections", "Blank Parts:=", nm, "Tool Parts:=", nm + "_slot"], ["NAME:SubtractParameters", "KeepOriginals:=", False])
    # cut away the half of the disc outside the window
    rect_sheet(nm + "_out", (cx - RD - 1.0) if sgn > 0 else cx, -RD - 1.0, cx if sgn > 0 else (cx + RD + 1.0), RD + 1.0, H)
    oEditor.Subtract(["NAME:Selections", "Blank Parts:=", nm, "Tool Parts:=", nm + "_out"], ["NAME:SubtractParameters", "KeepOriginals:=", False])
# PEC tabs under the diode-sheet ends
rect_sheet("TabL", -GAP / 2 - TAB, -SW / 2, -GAP / 2, SW / 2, H)
rect_sheet("TabR", GAP / 2, -SW / 2, GAP / 2 + TAB, SW / 2, H)
# diode sheets (series): A (x -0.5..0.0) R||C, B (x 0.0..0.5) L
rect_sheet("DiodeA", -GAP / 2, -SW / 2, 0.0, SW / 2, H)
rect_sheet("DiodeB", 0.0, -SW / 2, GAP / 2, SW / 2, H)

oEditor.CreateRectangle(["NAME:RectangleParameters", "IsCovered:=", True, "XStart:=", mm(-P / 2), "YStart:=", mm(-P / 2),
    "ZStart:=", "0mm", "Width:=", mm(P), "Height:=", mm(P), "WhichAxis:=", "Z"], attrs("Ground", "vacuum", True, "(128 128 128)"))
oEditor.CreateRectangle(["NAME:RectangleParameters", "IsCovered:=", True, "XStart:=", mm(-P / 2), "YStart:=", mm(-P / 2),
    "ZStart:=", mm(H + LID), "Width:=", mm(P), "Height:=", mm(P), "WhichAxis:=", "Z"], attrs("Lid", "vacuum", True, "(128 128 128)"))

oBnd = oDesign.GetModule("BoundarySetup")
for nm in ("PatchL", "PatchR", "TabL", "TabR", "Ground", "Lid"):
    oBnd.AssignPerfectE(["NAME:PerfE_" + nm, "Objects:=", [nm], "InfGroundPlane:=", False])


for nm, obj, xs, xe, opts in (("RLC_A", "DiodeA", -GAP / 2, 0.0, ["UseResist:=", True, "Resistance:=", "3ohm", "UseInduct:=", False, "UseCap:=", False]),
                              ("RLC_B", "DiodeB", 0.0, GAP / 2, ["UseResist:=", False, "UseInduct:=", True, "Inductance:=", "0.6nH", "UseCap:=", False])):
    oBnd.AssignLumpedRLC(["NAME:" + nm, "Objects:=", [obj],
        ["NAME:CurrentLine", "Start:=", [mm(xs), "0mm", mm(H)], "End:=", [mm(xe), "0mm", mm(H)]]] + opts)

def faces_at(x, y):
    ids = []
    for body, z in (("Substrate", H / 2.0), ("Air", H + LID / 2.0)):
        ids.append(int(oEditor.GetFaceByPosition(["NAME:FaceParameters", "BodyName:=", body,
                                                  "XPosition:=", mm(x), "YPosition:=", mm(y), "ZPosition:=", mm(z)])))
    return ids

# Lattice pairs. If a property name differs in your AEDT version, assign the same pairs in the GUI
# (HFSS > Boundaries > Assign > Primary / Secondary, phase delay = PHASE_X / PHASE_Y) -- see README.
try:
    # (tag, master-face centre, slave-face centre, phase, U vector start/end along the face)
    pairs = (("X", (-P / 2, 0.0), (P / 2, 0.0), PHASE_X, ((-P / 2, -P / 2), (-P / 2, P / 2)), ((P / 2, -P / 2), (P / 2, P / 2))),
             ("Y", (0.0, -P / 2), (0.0, P / 2), PHASE_Y, ((-P / 2, -P / 2), (P / 2, -P / 2)), ((-P / 2, P / 2), (P / 2, P / 2))))
    for tag, mc, sc, phase, mu, su in pairs:
        oBnd.AssignMaster(["NAME:Master" + tag, "Faces:=", faces_at(mc[0], mc[1]),
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(mu[0][0]), mm(mu[0][1]), "0mm"],
                                 "UPos:=", [mm(mu[1][0]), mm(mu[1][1]), "0mm"]],
            "ReverseV:=", False])
        oBnd.AssignSlave(["NAME:Slave" + tag, "Faces:=", faces_at(sc[0], sc[1]),
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(su[0][0]), mm(su[0][1]), "0mm"],
                                 "UPos:=", [mm(su[1][0]), mm(su[1][1]), "0mm"]],
            "ReverseU:=", False, "Master:=", "Master" + tag, "UseScanAngle:=", False, "PhaseDelay:=", phase])
except Exception as exc:
    oDesktop.AddMessage(oProject.GetName(), "EDGE_ON_along", 1, "Master/slave assignment failed (" + str(exc) + "): assign the X and Y pairs by hand, see README.")

oAna = oDesign.GetModule("AnalysisSetup")
oAna.InsertSetup("HfssEigen", ["NAME:Setup1", "MinimumFrequency:=", "8GHz", "NumModes:=", 6, "MaxDeltaFreq:=", 0.1,
    "ConvergeOnRealFreq:=", True, "MaximumPasses:=", 15, "MinimumPasses:=", 2, "MinimumConvergedPasses:=", 2,
    "PercentRefinement:=", 30, "IsEnabled:=", True, "BasisOrder:=", 1])
oEditor.FitAll()
oProject.SaveAs(oDesktop.GetProjectDirectory() + "/EDGE_ON_along.aedt", True)
oDesktop.AddMessage(oProject.GetName(), "EDGE_ON_along", 0, "Built. Set the phases, then Analyze: the bound mode is the lowest eigenmode whose field decays away from the patch plane.")
